{
  "findings": [
    {
      "check_id": "CKV_AZURE_27",
      "title": "Ensure that 'Email service and co-administrators' is 'Enabled' for MSSQL servers",
      "resource": "azurerm_mssql_server_security_alert_policy.alertpolicy6",
      "severity": "MEDIUM",
      "explanation": "The 'email_account_admins' field is not set to 'true', which means email notifications will not be sent to service and co-administrators. This could result in critical alerts being missed."
    },
    {
      "check_id": "CKV_AZURE_25",
      "title": "Ensure that 'Threat Detection types' is set to 'All'",
      "resource": "azurerm_mssql_server_security_alert_policy.alertpolicy6",
      "severity": "MEDIUM",
      "explanation": "The 'disabled_alerts' field disables specific threat detection types ('Sql_Injection' and 'Data_Exfiltration'). To ensure comprehensive threat detection, all types should be enabled."
    }
  ],
  "patched_code": "resource \"azurerm_mssql_server_security_alert_policy\" \"alertpolicy6\" {\n  resource_group_name        = azurerm_resource_group.example.name\n  server_name                = azurerm_mssql_server.mssql6.name\n  state                      = \"Enabled\"\n  storage_endpoint           = azurerm_storage_account.security_storage_account.primary_blob_endpoint\n  storage_account_access_key = azurerm_storage_account.security_storage_account.primary_access_key\n  retention_days             = 20\n  email_addresses            = [\"securityengineer@bridgecrew.io\"]\n  email_account_admins       = true\n  disabled_alerts            = []\n}",
  "fix_summary": "Enabled 'email_account_admins' to ensure email notifications are sent to service and co-administrators. Removed 'disabled_alerts' to enable all threat detection types."
}
